r='''args<-commandArgs(TRUE);O<-args[1];suppressPackageStartupMessages(library(Matrix));T<-file.path(O,"inputs/decontx_diagnostic");gm<-read.delim(file.path(T,"genes.tsv"));canon<-function(x){x<-toupper(x);a<-c(ATP5A1="ATP5F1A",ATP5B="ATP5F1B",ATP5C1="ATP5F1C",ATP5G1="ATP5MC1",ATP5O="ATP5PO",MRE11A="MRE11",PARK2="PRKN");i<-x%in%names(a);x[i]<-a[x[i]];x};gm$canonical<-canon(gm$canonical);P<-dirname(dirname(O));ctrl<-read.delim(gzfile(file.path(P,"11_reports/methods_complete_20261016_v13/supplement/S20_all_fixed_module_controls.tsv.gz")));cg<-setdiff(ctrl$gene[ctrl$dataset=="GSE314943" & ctrl$module=="PyroExec"],"DUSP5");mg<-c("PYCARD","CASP1","GSDMD","IL1B","IL18");out<-list();checks<-list();for(s in c("Saline_1","Saline_2","Saline_3","Silica_1","Silica_2","Silica_3")){res<-readRDS(file.path(T,paste0(s,"_decontx.rds")));cl<-res$decontXcounts;raw<-as(readMM(file.path(T,paste0(s,".mtx"))),"CsparseMatrix");rownames(raw)<-gm$gene_id;m<-read.delim(file.path(T,paste0(s,"_cells.tsv")));colnames(raw)<-m$cell;raw<-raw[rownames(cl),,drop=FALSE];mi<-which(gm$gene_id%in%rownames(cl) & gm$canonical%in%mg);ci<-which(gm$gene_id%in%rownames(cl) & gm$canonical%in%cg);D<-which(gm$canonical=="DUSP5");D<-intersect(gm$gene_id[D],rownames(cl));for(v in c("Raw","Corrected_original_library","Corrected_new_library")){xx<-if(v=="Raw")raw else cl;lib<-if(v=="Corrected_new_library")colSums(cl) else colSums(raw);cp<-xx%*%Diagonal(x=1e4/lib);logcp<-cp;logcp@x<-log1p(logcp@x);score<-colMeans(logcp[gm$gene_id[mi],,drop=FALSE])-colMeans(logcp[gm$gene_id[ci],,drop=FALSE]);keep<-m$decontx_cluster=="CD4_Treg";dusp<-colSums(cp[D,,drop=FALSE]);out[[paste(s,v)]]<-data.frame(sample=s,variant=v,cells=sum(keep),DUSP5=mean(dusp[keep]),PyroExec=mean(score[keep]),DUSP5_UMI=sum(xx[D,keep,drop=FALSE]),Pyro_members=length(mi),Pyro_controls=length(ci))};checks[[s]]<-data.frame(sample=s,cells=ncol(cl),features=nrow(cl),total_corrected=sum(cl),total_raw=sum(raw),list_names=paste(names(res),collapse=";"));};write.table(do.call(rbind,out),file.path(O,"06_novelty/decontx_Treg_program_samples.tsv"),sep="\\t",quote=FALSE,row.names=FALSE);write.table(do.call(rbind,checks),file.path(O,"provenance/decontx_integrity.tsv"),sep="\\t",quote=FALSE,row.names=FALSE)'''
(O/'code/decontx_summarize.R').write_text(r,encoding='utf-8');p=subprocess.run(['/mnt/BioDisk/wangmingyuan/miniconda3/envs/R_4.5.2/bin/Rscript','--vanilla',str(O/'code/decontx_summarize.R'),str(O)],capture_output=True,text=True);(O/'provenance/decontx_summarize.log').write_text(p.stdout+p.stderr,encoding='utf-8');assert p.returncode==0,p.stderr
import pandas as pd,numpy as np,itertools
