P=O.parents[1];M=P/'02_analysis/mechanism_step1_20260927_152218_s4V5eF';rd=lambda p:pd.read_csv(p,sep='\t');x=rd(O/'06_novelty/decontx_selected_gene_cell_counts.tsv.gz');meta=rd(O/'06_novelty/decontx_cell_metadata.tsv.gz');mac=rd(M/'comm_input/Mac_cells.tsv');x=x.merge(meta[['cell','Broad','decontx_cluster','contamination']],on='cell',validate='m:1');x['raw_CP10k']=x.raw_count*1e4/x.raw_library;x['corrected_rawlib_CP10k']=x.corrected_count*1e4/x.raw_library;x['corrected_newlib_CP10k']=x.corrected_count*1e4/x.corrected_library;rows=[]
for scope,cells in [('AllMac',set(mac.cell)),('AMlike',set(mac.loc[mac.subtype=='AMlike','cell']))]:
 b=x[x.cell.isin(cells)]
 for (sample,gene),z in b.groupby(['sample','gene']):rows.append(dict(scope=scope,sample=sample,gene=gene,cells=len(z),raw_UMI=z.raw_count.sum(),corrected_UMI=z.corrected_count.sum(),raw_CP10k=z.raw_CP10k.mean(),corrected_rawlib_CP10k=z.corrected_rawlib_CP10k.mean(),corrected_newlib_CP10k=z.corrected_newlib_CP10k.mean(),median_contamination=z.contamination.median()))
a=pd.DataFrame(rows);a.to_csv(O/'06_novelty/decontx_sender_sample_summary.tsv',sep='\t',index=False)
b=x.groupby(['sample','Broad','gene'],observed=True).agg(cells=('cell','size'),raw_CP10k=('raw_CP10k','mean'),corrected_CP10k=('corrected_newlib_CP10k','mean'),raw_UMI=('raw_count','sum'),corrected_UMI=('corrected_count','sum')).reset_index();b.to_csv(O/'06_novelty/finalist_competing_sources.tsv',sep='\t',index=False)
S=['Saline_1','Saline_2','Saline_3','Silica_1','Silica_2','Silica_3'];prog=rd(O/'06_novelty/decontx_Treg_program_samples.tsv');PERM=list(itertools.permutations(range(6)));WITH=[u+v for u in itertools.permutations(range(3)) for v in itertools.permutations(range(3,6))]
def exact(x,y,adj):
 x=rankdata(x);y=rankdata(y)
 for ix in ([np.arange(3),np.arange(3,6)] if adj else [np.arange(6)]):x[ix]-=x[ix].mean();y[ix]-=y[ix].mean()
 den=np.linalg.norm(x)*np.linalg.norm(y)
 if den<1e-12:return np.nan,np.nan
 r=x@y/den;null=[x[list(ix)]@y/den for ix in (WITH if adj else PERM)];return r,sum(abs(v)>=abs(r)-1e-12 for v in null)/len(null)
links=rd(O/'05_intersection/DUSP5_Treg_primary_links.tsv');results=[]
for variant,col in [('Raw','raw_CP10k'),('Corrected_original_library','corrected_rawlib_CP10k'),('Corrected_new_library','corrected_newlib_CP10k')]:
 z=prog[prog.variant==variant].set_index('sample').loc[S];pairs=[('DUSP5','PyroExec','Treg',z.DUSP5.to_numpy(),z.PyroExec.to_numpy())]
 for link in links.itertuples():
  v=a[(a.scope==link.sender)&(a.gene==link.ligand)].set_index('sample').reindex(S)[col].to_numpy();assert np.isfinite(v).all(),(variant,link.sender,link.ligand);pairs.append((link.ligand,'DUSP5',link.sender,v,z.DUSP5.to_numpy()))
 for xx,yy,sc,v,w in pairs:
  for adj in [False,True]:
   rho,p=exact(v,w,adj);results.append(dict(variant=variant,x=xx,y=yy,scope=sc,model='Adjusted' if adj else 'Pooled',rho=rho,P=p,n=6))
r=pd.DataFrame(results);r['family']=r.variant+'_'+r.model+'_diagnostic_pending_final_classification';r['BH']=np.nan;r.to_csv(O/'06_novelty/decontx_focal_associations.tsv',sep='\t',index=False,na_rep='NA');print(r.to_string(index=False));print('SENDER_RETENTION',a[a.gene.isin(['CDH1','OCLN','BMP1','H2-Q1'])].groupby(['scope','gene'])[['raw_UMI','corrected_UMI']].sum().to_string())
(O/'provenance/decontx_summary_complete.json').write_text(json.dumps({'status':'PASS','associations':len(r),'samples':6,'all_nonnegative':bool((x.corrected_count>=0).all())}),encoding='utf-8')